const doAI=async(mode:string,prompt?:string,requestedCourse?:string,examOptions?:any)=>{if(aiLock.current)return null;setAiError('');if(mode!=='chat'&&!current&&!requestedCourse){setAiError(t('chooseCourse'));return null}if(authRequired){notify(t('authRequired'));return null}aiLock.current=true;setAiMode(mode);setBusy(true);try{const r=await fetch('/api/ai',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode,courseId:requestedCourse||courseId||undefined,prompt,lang,outputLanguage,examOptions,history:mode==='chat'?chat.slice(-6).map(m=>({...m,content:m.content.slice(0,2000)})):undefined})});const d:any=await r.json();if(!r.ok)throw new Error(d.error);if(mode==='chat')void refresh(group).catch(error);else await refresh(group).catch(error);if(mode!=='chat')setCourseId(requestedCourse||courseId);if(mode==='chat'){setChat(c=>[...c,{role:'user',content:prompt||''},{role:'assistant',content:d.content,language:d.language}]);setQuestion('')}else if(mode==='quiz'){setPracticeTab('quiz');setQuiz(d.content);setAnswers({});setQuizDone(false);quizStart.current=Date.now();setView('practice')}else if(mode==='exam'){}else{setActiveArtifact({id:d.id,kind:'artifact',lang:d.language,type:mode,courseId,content:d.content,title:typeof d.content==='string'?d.content.split('\n')[0]:d.content.title||current?.title});setSlide(0);if(mode==='sheet'){setWorkTab('sheet');setView('work')}}return mode==='exam'?{...d.content,artifactId:d.id}:d.content;}catch(e:any){const labels:Record<string,string>={AI_CONTEXT_LIMIT:'aiContextLimit',LIMIT:'limit',AI_RATE_LIMIT:'ai_rate_limited',AI_FORMAT:'aiFormat',AI_UNAVAILABLE:'ai_missing',UNAUTHORIZED:'authRequired',INVALID:'invalidRequest',NOT_FOUND:'notFound'};setAiError(t(labels[e.message]||'error'));error(e);return null}finally{aiLock.current=false;setAiMode('');setBusy(false)}};
