const beginRecord=async()=>{if(recordLock.current||transcribeLock.current)return;recordLock.current=true;setRecordPending(true);let stream:MediaStream|undefined;try{if(!navigator.mediaDevices||!window.MediaRecorder)throw new Error('unsupported');stream=await openMicrophone(navigator.mediaDevices);if(!recordAlive.current){stream.getTracks().forEach(t=>t.stop());return}const mime=['audio/webm;codecs=opus','audio/mp4','audio/ogg;codecs=opus'].find(m=>MediaRecorder.isTypeSupported(m));const recorder=new MediaRecorder(stream,{...(mime?{mimeType:mime}:{}),audioBitsPerSecond:64000});const parts:Blob[]=[];media.current=recorder;recorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data)};recorder.onerror=()=>{notify(t('micBusy'));if(recorder.state!=='inactive')recorder.stop();stream?.getTracks().forEach(t=>t.stop());clearInterval(recordTimer.current);recordLock.current=false;setRecording(false)};recorder.onstop=()=>{clearInterval(recordTimer.current);const blob=new Blob(parts,{type:recorder.mimeType});setAudioBlob(blob);setAudioUrl(URL.createObjectURL(blob));stream?.getTracks().forEach(t=>t.stop());recordLock.current=false;setRecording(false)};recorder.start(1000);setTranscript('');setAudioUncertain(false);setRecordSeconds(0);setRecording(true);const started=Date.now();recordTimer.current=setInterval(()=>{setRecordSeconds(Math.floor((Date.now()-started)/1000));if(Date.now()-started>=30*60*1000&&recorder.state==='recording')recorder.stop()},1000);}catch(e:any){stream?.getTracks().forEach(t=>t.stop());recordLock.current=false;notify(t(e.name==='NotAllowedError'?'micDenied':e.message==='MIC_TIMEOUT'?'MIC_TIMEOUT':e.message==='unsupported'?'unsupported':'micBusy'))}finally{setRecordPending(false)}};
const transcribe=async()=>{if(!audioBlob||recordLock.current||transcribeLock.current)return;if(authRequired){notify(t('authRequired'));return}transcribeLock.current=true;setTranscribing(true);setBusy(true);try{if(audioBlob.size>20*1024*1024){notify(t('audioSizeLimit'));return}const f=new FormData();f.set('file',audioBlob,audioBlob instanceof File?audioBlob.name:'recording.'+(audioBlob.type.includes('mp4')?'mp4':audioBlob.type.includes('ogg')?'ogg':'webm'));f.set('language',recordLanguage);f.set('context',recordContext);const r=await uploadForm('/api/audio',f);const d:any=await r.json();if(!r.ok)throw new Error(d.error);setTranscript(d.text);setAudioUncertain(!!d.uncertain);await refresh(group);}catch(e:any){if(e.message==='AUDIO_EMPTY')notify(t('audioEmpty'));else error(e)}finally{transcribeLock.current=false;setTranscribing(false);setBusy(false)}};

