const calendarUI=(full=false)=><div className={'calendar-panel '+(full?'full':'')}><div className="section-heading"><div><h3>{full?t('calendar'):t('consistency')}</h3>{!full&&<p>{t('consistencyDesc')}</p>}</div>{!full&&<button className="icon-button" onClick={()=>navigate('calendar')} aria-label={t('viewAll')}><ArrowUpRight/></button>}</div><div className="month-header"><strong>{new Intl.DateTimeFormat(locales[lang],{month:'long',year:'numeric'}).format(month)}</strong><div><button className="icon-button" aria-label={t('previous')} onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()-1,1))}><ChevronLeft size={16}/></button><button className="icon-button" aria-label={t('next')} onClick={()=>setMonth(new Date(month.getFullYear(),month.getMonth()+1,1))}><ChevronRight size={16}/></button></div></div><div className="calendar-grid">{Array.from({length:7},(_,i)=><span className="weekday" key={'w'+i}>{new Intl.DateTimeFormat(locales[lang],{weekday:'narrow'}).format(new Date(2026,5,1+i))}</span>)}{monthCells(month.getFullYear(),month.getMonth()).map((date,i)=>{if(!date)return <span key={'e'+i}/>;const ss=sessions.filter(s=>s.date===date);const mins=ss.filter(s=>!s.planned).reduce((n,s)=>n+s.minutes,0);return <button key={date} className={'day '+(date===localDate()?'today ':'')+(date===selectedDate?'selected ':'')+(mins>=45?'strong ':mins?'active ':'')+(ss.some(s=>s.planned)?'planned':'')} aria-label={`${date} · ${mins} ${t('minutesShort')}`} aria-pressed={date===selectedDate} onClick={()=>setSelectedDate(date)}><span>{Number(date.slice(-2))}</span>{ss.some(s=>s.planned)&&<i/>}</button>})}</div><div className="calendar-legend"><span><i className="dot green"/>{t('done')}</span><span><i className="dot violet"/>{t('planned')}</span></div>{(full||selectedSessions.length>0)&&<div className="day-detail"><h4>{new Intl.DateTimeFormat(locales[lang],{day:'numeric',month:'long'}).format(new Date(selectedDate+'T12:00:00'))}</h4>{selectedSessions.length===0?<p>{t('none')}</p>:selectedSessions.map(s=><div className="session-row" key={s.id}><span className={'mini-icon '+(s.planned?'lilac':'mint')}><Clock size={16}/></span><div><strong>{s.subject}</strong><small>{s.minutes} min · {t(s.planned?'planned':'done')}</small></div><button className="icon-button" aria-label={t('delete')} onClick={()=>remove(s.id)}><Trash2 size={14}/></button></div>)}</div>}<button className="button secondary wide" onClick={()=>setModal('session')}><Plus size={16}/>{t('addSession')}</button></div>;
