{view==='practice'&&<><div className="page-intro"><div><p className="eyebrow">{t('practiceEyebrow')}</p><h1>{t('practice')}<span className="heading-dot">.</span></h1><p>{t('practiceDesc')}</p></div></div>{languageControl}<div className="studio-tabs practice-tabs">{[['quiz',Brain],['exam',FileText]].map(([key,Icon]:any)=><button key={key} className={practiceTab===key?'active':''} onClick={()=>setPracticeTab(key)}><Icon size={19}/>{t(key)}</button>)}</div>{aiError&&<div className="notice error-notice" role="alert">{aiError}</div>}<section hidden={practiceTab!=='exam'}><ExamStudio lang={lang} courses={courses} artifacts={artifacts} busy={busy} openedExam={examToOpen} onOpened={()=>setExamToOpen(null)} generate={(id,options)=>doAI('exam',undefined,id,options)} onDelete={remove}/></section><section hidden={practiceTab!=='quiz'}>{!quiz?<><div className="practice-launch"><div className="practice-art"><Brain size={66}/><span>?</span><i>✦</i></div><h2>{t('noQuiz')}</h2><div className="inline-form"><select value={courseId} onChange={e=>setCourseId(e.target.value)}><option value="">{t('chooseCourse')}</option>{courses.map(c=><option value={c.id} key={c.id}>{c.title}</option>)}</select><button className="button primary" disabled={busy||!courseId} onClick={()=>doAI('quiz')}><Sparkles size={17}/>{t('generate')}</button></div><small>{t('aiNote')}</small></div><div className="saved-quizzes">{artifacts.filter(a=>a.type==='quiz').map(a=><button className="panel saved-quiz" key={a.id} onClick={()=>{setCourseId(a.courseId||'');setQuiz(a.content);setAnswers({});setQuizDone(false);quizStart.current=Date.now()}}><Brain/><span>{a.title}</span><Play size={17}/></button>)}</div></>:<div className="quiz-sheet"><div className="section-heading"><h2>{quiz.title}</h2><button className="icon-button" onClick={()=>setQuiz(null)} aria-label={t('close')}><X/></button></div>{quizDone&&<div className="quiz-result"><CheckCircle2 size={38}/><span>{t('result')}</span><strong>{quiz.questions.filter((q:any,i:number)=>answers[i]===q.answer).length} / {quiz.questions.length}</strong></div>}{quiz.questions.map((q:any,i:number)=><div className="quiz-question" key={i}><div className="question-number">{String(i+1).padStart(2,'0')}</div><div><h3><AIMessage content={q.question} inline/></h3><div className="quiz-options">{q.options.map((o:string,j:number)=><button key={j} className={(answers[i]===j?'chosen ':'')+(quizDone&&q.answer===j?'correct ':'')+(quizDone&&answers[i]===j&&q.answer!==j?'wrong':'')} aria-pressed={answers[i]===j} onClick={()=>!quizDone&&setAnswers({...answers,[i]:j})} disabled={quizDone}><span>{String.fromCharCode(65+j)}</span><AIMessage content={o} inline/>{quizDone&&q.answer===j&&<strong className="answer-label"><Check size={17}/>{t('correctAnswer')}</strong>}{quizDone&&answers[i]===j&&q.answer!==j&&<strong className="answer-label"><X size={17}/>{t('yourMistake')}</strong>}</button>)}</div>{quizDone&&<p className={'answer-verdict '+(answers[i]===q.answer?'right':'incorrect')}>{t(answers[i]===q.answer?'correctAnswer':'yourMistake')}</p>}{quizDone&&<p className="explanation"><strong>{t('explain')} : </strong><AIMessage content={q.explanation} inline/></p>}</div></div>)}{!quizDone&&<p className="quiz-progress" role="status">{Object.keys(answers).length} / {quiz.questions.length} {t('answered')}</p>}{quizDone?<div className="button-row"><button className="button primary" onClick={()=>{setQuizDone(false);setAnswers({});quizStart.current=Date.now()}}>{t('retry')}</button><button className="button secondary" onClick={()=>{setActiveArtifact({id:'result',kind:'artifact',content:quiz.title+'\n'+quiz.questions.filter((q:any,i:number)=>answers[i]===q.answer).length+'/'+quiz.questions.length,title:quiz.title});setModal('share')}}>{t('share')}</button></div>:<button className="button primary wide" disabled={Object.keys(answers).length!==quiz.questions.length||busy} onClick={async()=>{setBusy(true);try{const score=quiz.questions.filter((q:any,i:number)=>answers[i]===q.answer).length;setQuizDone(true);await save('attempt',{title:quiz.title,score,total:quiz.questions.length,courseId});const minutes=Math.floor((Date.now()-quizStart.current)/60000);if(minutes>=1)await save('session',{date:localDate(),minutes:Math.min(720,minutes),subject:current?.subject||t('quiz'),mode:'quiz',planned:false});setQuizDone(true)}catch(e){error(e)}finally{setBusy(false)}}}>{t('check')}<ArrowRight size={17}/></button>}</div>}</section></>}

{view==='studio'&&<><div className="page-intro"><div><p className="eyebrow">{t('studioEyebrow')}</p><TechHeading text={t('studio')}/><p>{t('studioDesc')}</p></div></div><div className="studio-motion-banner"><StudioWaves/><span className="studio-motion-caption">{t('studioCaption')}</span></div><div className="studio-tabs">{[['audio',Mic],['voice',Headphones]].map(([key,Icon]:any)=><button key={key} className={studioTab===key?'active':''} onClick={()=>{if(recording){notify(t('recording'));return}setStudioTab(key);setActiveArtifact(null)}}><Icon size={19}/>{t(key)}</button>)}</div>{studioTab==='audio'?<div className="studio-card"><div className={'recording-orb '+(recording?'recording':'')}><Mic size={44}/><i/><i/></div><h2>{t(recording?'recording':'record')}</h2><p className="studio-copy">{t('consent')}</p><div className="language-controls"><label>{t('recordLanguage')}<select value={recordLanguage} disabled={recording||recordPending||transcribing} onChange={e=>setRecordLanguage(e.target.value)}><option value="auto">{t('recordAuto')}</option>{Object.entries({fr:'Français',en:'English',de:'Deutsch',es:'Español'}).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><label>{t('recordContext')}<input value={recordContext} maxLength={500} disabled={transcribing} onChange={e=>setRecordContext(e.target.value)} placeholder={t('recordContextHelp')}/></label></div><p>{t('recordLimit')}{recording&&` · ${Math.floor(recordSeconds/60)}:${String(recordSeconds%60).padStart(2,'0')}`}</p><div className={'waveform '+(recording?'live':'')} aria-hidden="true">{Array.from({length:37},(_,i)=><i key={i} style={{height:(12+Math.sin(i*1.7)**2*42)+'px',animationDelay:i*.08+'s'}}/>)}</div><button className={'button '+(recording?'danger':'primary')} disabled={recordPending||transcribing} onClick={()=>recording?media.current?.stop():beginRecord()}>{recording?<StopCircle size={19}/>:<Mic size={19}/>} {t(recording?'stop':'recordStart')}</button><label className="audio-upload">{t('audioFallback')}<input type="file" accept="audio/webm,audio/mp4,audio/mpeg,audio/wav,audio/ogg,.m4a" disabled={recording||recordPending||transcribing} onChange={e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>20*1024*1024){notify(t('audioSizeLimit'));return}setAudioBlob(file);setAudioUrl(URL.createObjectURL(file));setTranscript('');setAudioUncertain(false)}}/><small>{t('audioSizeLimit')}</small></label>{audioUrl&&!recording&&!recordPending&&<div className="audio-result"><audio controls src={audioUrl}/><div className="button-row"><a className="button secondary" href={audioUrl} download={audioBlob instanceof File?audioBlob.name:'make-it-happen-recording.'+(audioBlob?.type.includes('mp4')?'mp4':audioBlob?.type.includes('ogg')?'ogg':'webm')}><Download size={16}/>{t('download')}</a><button className="button primary" disabled={busy||recording} onClick={transcribe}>{transcribing?<Loader2 className="spin" size={16}/>:<Sparkles size={16}/>} {t(transcribing?'transcribingAudio':'transcribe')}</button></div></div>}{transcript&&<div className="transcript"><h3>{t('transcription')}</h3>{audioUncertain&&<p role="status">{t('audioUncertain')}</p>}<textarea aria-label={t('transcription')} value={transcript} onChange={e=>setTranscript(e.target.value)}/><button className="button primary" onClick={()=>{setEditId(null);setFormText(transcript);setFileId('');setModal('course')}}>{t('addCourse')}</button></div>}</div>:<LanguageCoach ui={lang} onUsed={()=>refresh(group)}/>}</>}
{view==='groups'&&<><div className="page-intro"><div><p className="eyebrow">YOUR STUDY CIRCLE</p><h1>{t('groupTitle')}</h1><p>{t('groupDesc')}</p></div><button className="button primary" onClick={()=>setModal('createGroup')}><Plus size={17}/>{t('createGroup')}</button></div><div className="groups-layout"><aside className="groups-list"><div className="section-heading"><h3>{t('groups')}</h3><button className="icon-button" onClick={()=>setModal('joinGroup')} aria-label={t('joinGroup')}><Plus size={17}/></button></div>{groups.map((g,i)=><button className={'group-item '+(group===g.id?'active':'')} key={g.id} onClick={()=>setGroup(g.id)}><span className={'group-avatar '+colors[i%4]}>{g.name.slice(0,1).toUpperCase()}</span><span><strong>{g.name}</strong><small>{t('private')}</small></span></button>)}<button className="button secondary wide" onClick={()=>setModal('joinGroup')}>{t('joinGroup')}</button><div className="friends-heading"><h3>{t('friends')}</h3><button className="icon-button" onClick={()=>setModal('friend')} aria-label={t('addFriend')}><Plus size={17}/></button></div>{friends.map(f=><div className="friend-row" key={f.peer}><span className="avatar tiny">{f.name.slice(0,1).toUpperCase()}</span><div><strong>{f.name}</strong>{f.status==='sent'&&<small>{t('pending')}</small>}</div>{f.status==='received'&&<button className="icon-button" aria-label={t('accept')} onClick={async()=>{try{await api('acceptFriend',{peer:f.peer});await refresh(group)}catch(e){error(e)}}}><Check size={16}/></button>}<button className="icon-button" aria-label={t('delete')} onClick={async()=>{try{await api('removeFriend',{peer:f.peer});await refresh(group)}catch(e){error(e)}}}><X size={14}/></button></div>)}{profile&&<div className="friend-code"><small>{t('code')}</small><button onClick={()=>copy(profile.code)}><code>{profile.code}</code><Copy size={14}/></button></div>}</aside><section className="group-conversation">{currentGroup?<><div className="group-header"><span className="group-avatar lilac"><Users size={22}/></span><div><h3>{currentGroup.name}</h3><small>{t('private')}</small></div><button className="button secondary" onClick={()=>copy(currentGroup.code)}><Copy size={15}/>{t('code')}</button></div><div className="messages">{!messages.length&&<div className="group-empty-small"><MessageCircle size={40}/><p>{t('noMessages')}</p></div>}{messages.map(m=><div className={'group-message '+(m.owner===profile?.id?'mine':'')} key={m.id}><span className="message-author">{m.name}<small>{new Intl.DateTimeFormat(locales[lang],{hour:'2-digit',minute:'2-digit'}).format(new Date(m.created))}</small></span><p>{m.body}</p></div>)}</div><form className="group-input" onSubmit={async e=>{e.preventDefault();const form=e.currentTarget;const f=new FormData(form);try{await api('message',{group,text:f.get('message')});form.reset();await refresh(group)}catch(e){error(e)}}}><input name="message" required maxLength={10000} placeholder={t('message')}/><button className="send-button" aria-label={t('send')}><Send size={18}/></button></form></>:<div className="group-empty"><div className="friends-art"><span className="friend-orb mint">✳</span><span className="friend-orb lilac">✦</span><span className="friend-orb peach">☺</span></div><h2>{t('groupEmpty')}</h2><p>{t('groupDesc')}</p><button className="button primary" onClick={()=>setModal('createGroup')}><Plus size={17}/>{t('createGroup')}</button></div>}</section></div></>}
