{modal==='session'&&<Modal lang={lang} title={t('addSession')} onClose={()=>setModal('')}><form onSubmit={onSessionSave} className="form-stack"><label>{t('subject')}<input name="subject" required maxLength={80} defaultValue={current?.subject||''} list="session-subjects"/><datalist id="session-subjects">{[...new Set(courses.map(c=>c.subject))].map(s=><option key={s}>{s}</option>)}</datalist></label><div className="form-two"><label>{t('date')}<input type="date" name="date" defaultValue={selectedDate} min="2000-01-01" max="2100-12-31" required/></label><label>{t('duration')}<input type="number" name="minutes" defaultValue={25} min={1} max={720} required/></label></div><label className="checkbox-row"><input type="checkbox" name="planned" defaultChecked={selectedDate>localDate()}/>{t('planning')}</label><button className="button primary" disabled={busy}><Check size={17}/>{t('save')}</button></form></Modal>}
{modal==='focus'&&<Modal lang={lang} title={t('focus')} onClose={()=>setModal('')}><div className="focus-modal"><p>{t('focusText')}</p><div className={'timer-ring '+(running?'running':'')}><span>{String(Math.floor(timer/60)).padStart(2,'0')}<i>:</i>{String(timer%60).padStart(2,'0')}</span><small>/ 25:00</small></div><input placeholder={t('subject')} value={timerSubject} onChange={e=>setTimerSubject(e.target.value)} maxLength={80}/><div className="button-row"><button className="button primary" onClick={()=>setRunning(!running)}>{running?<Pause size={17}/>:<Play size={17}/>} {t(running?'pause':timer?'resume':'start')}</button><button className="button secondary" onClick={()=>{setRunning(false);setTimer(0)}}>{t('reset')}</button></div><button className="text-button" disabled={busy} onClick={finishFocus}><Check size={17}/>{t('finish')}</button></div></Modal>}
