{pendingDelete&&<Modal lang={lang} title={t('confirmDelete')} onClose={()=>{if(!deleteLock.current)setPendingDelete(null)}}><div className="form-stack"><p>{rows.find(r=>r.id===pendingDelete)?.title||rows.find(r=>r.id===pendingDelete)?.name||t('resources')}</p><p>{t('deleteHelp')}</p><div className="button-row"><button className="button secondary" disabled={deleting} onClick={()=>setPendingDelete(null)}>{t('cancel')}</button><button className="button primary" disabled={deleting} onClick={confirmRemoval}>{deleting?<Loader2 className="spin" size={18}/>:<Trash2 size={18}/>} {t(deleting?'loading':'delete')}</button></div></div></Modal>}
